window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f2fd42be43723661"]={"versions": [{"id": "FIG-f2fd42be43723661", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm (<code>act Checksum OK</code>) aus der AUTOSAR E2E-Bibliothek (Classic Platform). Es spezifiziert den Algorithmus zur Prüfsummenvalidierung (<code>Checksum OK</code>) für ein E2E-Profil (konkret unter Nutzung von CRC-8-H2F über Nutzdaten und DataID).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Startknoten</strong>: Initialer Kontrollflussstart der Aktivität.\n</li><li><strong>Aktionszustand</strong>: Aufruf der CRC-Routine <code>CalcualtedCRC = Crc_CalculateCRC8H2F() computed over Data[1], Data[2], … Data[Config-&gt;DataLength/8-1], DataID</code>.\n</li><li><strong>Entscheidungsknoten (Decision Node)</strong>: Bedingungsprüfung <code>CalculatedCRC == Data[0]</code>.\n</li><li><strong>Bedingungszweige (Guards)</strong>:\n<ul class=\"fig-list\"><li><code>[TRUE]</code>: Führt zum linken Endknoten mit Rückgabewert <code>return TRUE</code>.\n</li><li><code>[FALSE]</code>: Führt zum rechten Endknoten mit Rückgabewert <code>return FALSE</code>.\n</li></ul>\n</li><li><strong>Aktivitätsendknoten</strong>: Zwei Endzustände (Bullseye-Symbole) zur Beendigung der Aktivität mit dem jeweiligen booleschen Rückgabewert.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Nach dem Eintritt am Startknoten wird die CRC-Berechnung über die Datenbytes ab Index 1 bis zum letzten Datenbyte (<code>Config-&gt;DataLength/8-1</code>) sowie die konfigurierte <code>DataID</code> mittels <code>Crc_CalculateCRC8H2F()</code> ausgeführt und in <code>CalcualtedCRC</code> abgelegt.\n</li><li>Am nachfolgenden Entscheidungsknoten wird der berechnete Prüfsummenwert mit dem im ersten Datenbyte empfangenen Wert <code>Data[0]</code> verglichen (<code>CalculatedCRC == Data[0]</code>).\n</li><li>Bei Übereinstimmung (<code>[TRUE]</code>) verzweigt der Kontrollfluss zum linken Aktivitätsendknoten und liefert <code>TRUE</code> zurück.\n</li><li>Bei Nichtübereinstimmung (<code>[FALSE]</code>) verzweigt der Kontrollfluss zum rechten Aktivitätsendknoten und liefert <code>FALSE</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Logik definiert die normative Überprüfung der Datenintegrität für E2E-Nachrichten:</p>\n<ul class=\"fig-list\"><li>Datenbyte 0 (<code>Data[0]</code>) fungiert als Ablageort der übertragenen 8-Bit-Prüfsumme.\n</li><li>Die Berechnung schließt sämtliche Nutzdatenbytes ab Byte 1 bis <code>Config-&gt;DataLength/8 - 1</code> sowie die konfigurierte Daten-ID (<code>DataID</code>) ein.\n</li><li>Ein fehlerhafter oder nicht übereinstimmender CRC führt deterministisch zu einem negativen Prüfergebnis (<code>FALSE</code>), während Übereinstimmung <code>TRUE</code> meldet. Implementierer müssen beachten, dass der Bezeichner <code>CalcualtedCRC</code> im Diagrammtext einen Tippfehler enthält, funktional aber <code>CalculatedCRC</code> meint.\n</li></ul>"}, {"id": "FIG-f9f0dc56ce660f26", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm aus der AUTOSAR E2E-Bibliothek (Classic Platform). Es spezifiziert den Ablauf zur Prüfsummenvalidierung für ein E2E-Profil mittels CRC-8-H2F über Datenbytes und DataID ohne expliziten Diagrammrahmen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Startknoten</strong>: Initialer Kontrollflussstart der Aktivität.\n</li><li><strong>Aktionszustand</strong>: Aufruf der CRC-Routine <code>CalcualtedCRC = Crc_CalculateCRC8H2F() computed over Data[1], Data[2], … Data[Config-&gt;DataLength/8-1], DataID</code>.\n</li><li><strong>Entscheidungsknoten (Decision Node)</strong>: Bedingungsprüfung <code>CalculatedCRC == Data[0]</code>.\n</li><li><strong>Bedingungszweige (Guards)</strong>:\n<ul class=\"fig-list\"><li><code>[TRUE]</code>: Verzweigung zum linken Endknoten.\n</li><li><code>[FALSE]</code>: Verzweigung zum rechten Endknoten.\n</li></ul>\n</li><li><strong>Aktivitätsendknoten</strong>: Zwei Endzustände (Bullseye-Symbole) zur Terminierung des Ablaufs je nach Prüfergebnis.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Nach dem Eintritt am Startknoten wird die Prüfsummenberechnung über die Datenbytes ab Index 1 bis <code>Config-&gt;DataLength/8-1</code> sowie die <code>DataID</code> via <code>Crc_CalculateCRC8H2F()</code> ausgeführt und der Zwischenwert <code>CalcualtedCRC</code> gebildet.\n</li><li>Der Entscheidungsknoten prüft das Prädikat <code>CalculatedCRC == Data[0]</code>.\n</li><li>Bei Erfüllung (<code>[TRUE]</code>) folgt der Kontrollfluss dem linken Pfad zum linken Endknoten.\n</li><li>Bei Nichterfüllung (<code>[FALSE]</code>) folgt der Kontrollfluss dem rechten Pfad zum rechten Endknoten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Logik definiert die normative Überprüfung der Datenintegrität für E2E-Nachrichten:</p>\n<ul class=\"fig-list\"><li>Datenbyte 0 (<code>Data[0]</code>) fungiert als Ablageort der übertragenen 8-Bit-Prüfsumme.\n</li><li>Die Berechnung schließt sämtliche Nutzdatenbytes ab Byte 1 bis <code>Config-&gt;DataLength/8 - 1</code> sowie die konfigurierte Daten-ID (<code>DataID</code>) ein.\n</li><li>Ein fehlerhafter oder nicht übereinstimmender CRC führt deterministisch zu einem negativen Prüfergebnis (<code>FALSE</code>), während Übereinstimmung <code>TRUE</code> meldet. Implementierer müssen beachten, dass der Bezeichner <code>CalcualtedCRC</code> im Diagrammtext einen Tippfehler enthält, funktional aber <code>CalculatedCRC</code> meint.\n</li></ul>"}], "trans": [{"from": "FIG-f2fd42be43723661", "to": "FIG-f9f0dc56ce660f26", "fr": "R3.2.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>UML-Rahmen &amp; Diagrammtitel</strong>: Der umgebende Aktivitätsrahmen <code>act Checksum OK</code> sowie die interne Überschrift <code>Checksum OK</code> oberhalb des Startknotens wurden entfernt.\n</li><li><strong>Endknoten-Beschriftung</strong>: Die textuellen Ausgabezuordnungen <code>return TRUE</code> und <code>return FALSE</code> unterhalb der Aktivitätsendknoten wurden entfernt (die Zweigsemantik verbleibt an den Guards <code>[TRUE]</code> und <code>[FALSE]</code>).\n</li></ul>"}]};
